function parse(tokens) {
  let i = 0;
  const peek = () => tokens[i];
  const eat = (t) => { if (peek() !== t) throw new Error(`기대: ${t}, 실제: ${peek()}`); i++; };

  function expr() {                       // + -
    let node = term();
    while (peek() === '+' || peek() === '-') { const op = tokens[i++]; node = { op, left: node, right: term() }; }
    return node;
  }
  function term() {                       // * /  (더 세게 묶인다)
    let node = factor();
    while (peek() === '*' || peek() === '/') { const op = tokens[i++]; node = { op, left: node, right: factor() }; }
    return node;
  }
  function factor() {
    if (peek() === '(') { eat('('); const n = expr(); eat(')'); return n; }
    return { num: Number(tokens[i++]) };
  }
  return expr();
}

function evalNode(n) {
  if ('num' in n) return n.num;
  const a = evalNode(n.left), b = evalNode(n.right);
  return { '+': a + b, '-': a - b, '*': a * b, '/': a / b }[n.op];
}
evalNode(parse(tokenize('1 + 2 * (3 - 1)')));   // 5
